import sys
import xml.etree.ElementTree as ET
from collections import defaultdict
from datetime import datetime, timedelta

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    limits = {}
    for limit_elem in root.findall('limit'):
        category = limit_elem.get('category')
        max_lines = int(limit_elem.get('max_lines'))
        window_seconds = int(limit_elem.get('window_seconds'))
        limits[category] = {'max_lines': max_lines, 'window_seconds': window_seconds}
    return limits

def process_input(limits):
    category_data = defaultdict(list)
    dropped_categories = defaultdict(int)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('\t', 1)
        if len(parts) != 2:
            continue
        category, message = parts
        current_time = datetime.now()

        if category not in limits:
            print(message, end='\n')
            continue

        limit = limits[category]
        window = timedelta(seconds=limit['window_seconds'])
        now = current_time.timestamp()
        valid_lines = [t for t, _ in category_data[category] if now - t >= window]

        if len(valid_lines) < limit['max_lines']:
            category_data[category].append((now, message))
            print(message, end='\n')
        else:
            dropped_categories[category] += 1

    for category in sorted(dropped_categories.keys()):
        sys.stderr.write(f'dropped {category} {dropped_categories[category]}\n')

if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(1)
    limits = parse_xml(sys.argv[1])
    process_input(limits)
